"""Authored scenario details and explicit small wording repairs; no acceptance."""
import sys,json,re
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2]
sys.path.insert(0,str(ROOT/'tools'))
from edit_chapter import load,save,transform
def read(p):return json.loads((ROOT/p).read_text(encoding='utf8'))
def write(p,o):(ROOT/p).write_text(json.dumps(o,ensure_ascii=False,indent=2)+'\n',encoding='utf8',newline='\n')
batch=read('editorial/current-batch.json');course=read('course.json');by={c['id']:c for c in course['chapters']}
c=load()
for ident in batch['chapters']:
 transform(by[ident]['path'],lambda t:t.replace('\u200b','').replace('потoкен','потокен').replace('четыре двух super-scale','четыре байта двух масштабов FP16'),
  'Удалены невидимые разделители расписания и исправлены опечатки; числовые условия сохранены.',c)
save(c)
